OLD_ACCENTS = ("#0b5cad", "#7db8f5")  # the placeholder blue: nobody chose it


def carry_over(apps, schema_editor):
    """EXPAND. The old `identity` row is left alone: the previous release still reads it while this one starts.
    CONTRACT (0003, next release) deletes it. Old logos were media library files, which cannot be trusted as
    logos; they are uploaded again, and checked, on the Appearance page."""
    from newsplatform.site_config.theme import derive

    Section = apps.get_model("site_config", "SettingsSection")
    old = Section.objects.filter(key="identity").first()
    if old is None or Section.objects.filter(key="brand").exists():
        return
    identity = {k: old.data[k] for k in ("brand_name", "tagline_sw", "tagline_en") if k in old.data}
    look = {}
    light = str(old.data.get("accent_light", OLD_ACCENTS[0])).lower()
    dark = str(old.data.get("accent_dark", OLD_ACCENTS[1])).lower()
    if light != OLD_ACCENTS[0]:
        look["color"] = derive.nearest(light)
        if dark != OLD_ACCENTS[1]:
            look["dark_color"] = derive.nearest(look["color"], dark, "dark")
    Section.objects.create(key="brand", data={"identity": identity, "appearance": look})


